exercises.solution:
import re

def identifiant_valide(texte):
    return bool(re.fullmatch(r"[a-z][a-z0-9_]{2,15}", texte))

import re

def normaliser_tel(texte):
    brut = texte.replace(" ", "")
    m = re.fullmatch(r"(\+228)?(\d{8})", brut)
    if m is None:
        return None
    return "+228" + m.group(2)

