import re

def valider_inscription(formulaire):
    erreurs = []
    if not re.fullmatch(r"[a-z][a-z0-9_]{2,15}", formulaire["identifiant"]):
        erreurs.append("identifiant invalide")
    if not re.fullmatch(r"(\+228)?\d{8}", formulaire["telephone"].replace(" ", "")):
        erreurs.append("téléphone invalide")
    age = formulaire["age"]
    if not re.fullmatch(r"\d{2}", age) or not 10 <= int(age) <= 99:
        erreurs.append("âge invalide")
    return erreurs
